126	const asyncWebFrameMethods = function (requestId, method, callback, ...args) {
127	  return new Promise((resolve, reject) => {
128	    this.send('ELECTRON_INTERNAL_RENDERER_ASYNC_WEB_FRAME_METHOD', requestId, method, args)
129	    ipcMain.once(`ELECTRON_INTERNAL_BROWSER_ASYNC_WEB_FRAME_RESPONSE_${requestId}`, function (event, error, result) {
130	      if (error == null) {
131	        if (typeof callback === 'function') callback(result)
132	        resolve(result)
133	      } else {
134	        if (error.__ELECTRON_SERIALIZED_ERROR__ && errorConstructors[error.name]) {
135	          const rehydratedError = new errorConstructors[error.name](error.message)
136	          rehydratedError.stack = error.stack
137	
138	          reject(rehydratedError)
139	        } else {
140	          reject(error)
141	        }
142	      }
143	    })
144	  })
145	}
